    10	/**
    11	 * A compose health check is advisory: on a freshly-created network, DNS and
    12	 * PostgreSQL can still take a moment to become reachable after Compose starts
    13	 * the migrator. Retrying here makes migrations safe to run both in Compose and
    14	 * as a standalone operational command.
    15	 */
    16	async function waitForDatabase(): Promise<void> {
    17	  const attempts = 30;
    18	  let lastError: unknown;
    19	
    20	  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    21	    try {
    22	      await pool.query('SELECT 1');
    23	      return;
    24	    } catch (error) {
    25	      lastError = error;
    26	      if (attempt < attempts) {
    27	        await new Promise((resolveDelay) => setTimeout(resolveDelay, 1_000));
    28	      }
    29	    }
    30	  }
    31	
    32	  throw new Error(`database did not become reachable after ${attempts} seconds`, { cause: lastError });
    33	}
