    35	await waitForDatabase();
    36	await pool.query(`CREATE TABLE IF NOT EXISTS public.schema_migrations(
    37	  name text PRIMARY KEY, checksum text NOT NULL, applied_at timestamptz NOT NULL DEFAULT now()
    38	)`);
    39	const files = (await readdir(migrationsDirectory)).filter((name) => /^\d+.*\.sql$/.test(name)).sort();
    40	for (const name of files) {
    41	  const sql = await readFile(resolve(migrationsDirectory, name), 'utf8');
    42	  const checksum = createHash('sha256').update(sql).digest('hex');
    43	  await transaction(async (client) => {
