    45	    const applied = await client.query<{ checksum: string }>(`SELECT checksum FROM public.schema_migrations WHERE name=$1`, [name]);
    46	    if (applied.rows[0]?.checksum === checksum) return;
    47	    if (applied.rows[0]) throw new Error(`migration ${name} was modified after it was applied`);
    48	    await client.query(sql);
    49	    await client.query(`INSERT INTO public.schema_migrations(name,checksum) VALUES($1,$2)`, [name, checksum]);
    50	  });
    51	  console.log(JSON.stringify({ status: 'applied', migration: name }));
    52	}
