import type { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { authenticate } from '../../../packages/auth/src/api-key.js';
import { createPaymentSchema, createRefundSchema } from '../../../packages/contracts/src/domain.js';
import { PaymentRepository } from './repository.js';
import { PaymentService } from './service.js';
import { InvoiceService } from './invoices.js';

const invoiceSchema = z.object({
  customerId: z.string().uuid(), currency: z.string().length(3).transform((v) => v.toUpperCase()),
  tax: z.number().int().nonnegative().default(0), lines: z.array(z.object({
    description: z.string().min(1).max(500),
    quantity: z.number().int().positive(), unitAmount: z.number().int().positive()
  })).min(1).max(100)
});

export async function paymentRoutes(app: FastifyInstance): Promise<void> {
  const service = new PaymentService();
  const repository = new PaymentRepository();
  const invoices = new InvoiceService();
  app.get('/health', async () => ({ status: 'ok', service: 'payment-service' }));
  app.post('/v1/payments', async (request, reply) => {
    const principal = await authenticate(request, 'payments:write');
    const key = request.headers['idempotency-key'];
    if (typeof key !== 'string' || key.length < 8) return reply.code(400).send({ error: 'valid_idempotency_key_required' });
    const result = await service.create(principal.merchantId, request.headers.authorization!, key, createPaymentSchema.parse(request.body));
    return reply.code(result.status).send(result.body);
  });
  app.get('/v1/payments', async (request) => {
    const principal = await authenticate(request, 'payments:read');
    const query = z.object({ customerId: z.string().uuid().optional(), limit: z.coerce.number().int().min(1).max(100).default(20) }).parse(request.query);
    return { data: await repository.list(principal.merchantId, query.customerId, query.limit) };
  });
  app.get('/v1/payments/:id', async (request, reply) => {
    const principal = await authenticate(request, 'payments:read');
    const { id } = z.object({ id: z.string().uuid() }).parse(request.params);
    return await repository.find(principal.merchantId, id) ?? reply.code(404).send({ error: 'payment_not_found' });
  });
  app.post('/v1/payments/:id/refunds', async (request, reply) => {
    const principal = await authenticate(request, 'payments:write');
    const { id } = z.object({ id: z.string().uuid() }).parse(request.params);
    return reply.code(202).send(await service.refund(principal.merchantId, id, createRefundSchema.parse(request.body)));
  });
  app.post('/v1/invoices', async (request, reply) => {
    const principal = await authenticate(request, 'payments:write');
    return reply.code(201).send(await invoices.create(principal.merchantId, request.headers.authorization!, invoiceSchema.parse(request.body)));
  });
}
import { createHash } from 'node:crypto';
import type pg from 'pg';

export function requestHash(value: unknown): string {
  return createHash('sha256').update(JSON.stringify(value)).digest('hex');
}

export async function reserveIdempotency(
  client: pg.PoolClient,
  merchantId: string,
  scope: string,
  key: string,
  hash: string,
): Promise<{ status: number; body: unknown } | undefined> {
  const inserted = await client.query(
    `INSERT INTO operations.idempotency_keys(merchant_id,scope,key,request_hash,expires_at)
     VALUES($1,$2,$3,$4,now()+interval '24 hours') ON CONFLICT DO NOTHING`,
    [merchantId, scope, key, hash],
  );
  if (inserted.rowCount) return undefined;
  const existing = await client.query<{ request_hash: string; response_status: number | null; response_body: unknown }>(
    `SELECT request_hash,response_status,response_body FROM operations.idempotency_keys
     WHERE merchant_id=$1 AND scope=$2 AND key=$3 FOR UPDATE`, [merchantId, scope, key],
  );
  const row = existing.rows[0];
  if (!row || row.request_hash !== hash) throw Object.assign(new Error('idempotency key reused with different request'), { statusCode: 409 });
  if (row.response_status === null) throw Object.assign(new Error('request with this idempotency key is in progress'), { statusCode: 409 });
  return { status: row.response_status, body: row.response_body };
}

export async function completeIdempotency(
  client: pg.PoolClient, merchantId: string, scope: string, key: string, status: number, body: unknown,
): Promise<void> {
  await client.query(
    `UPDATE operations.idempotency_keys SET response_status=$4,response_body=$5
     WHERE merchant_id=$1 AND scope=$2 AND key=$3`, [merchantId, scope, key, status, body],
  );
}
import type pg from 'pg';
import { v4 as uuid } from 'uuid';
import type { EventEnvelope } from '../../contracts/src/events.js';

export async function addOutboxEvent(
  client: pg.PoolClient,
  event: Omit<EventEnvelope, 'eventId' | 'occurredAt' | 'eventVersion'> & { eventVersion?: number },
): Promise<EventEnvelope> {
  const envelope: EventEnvelope = {
    ...event,
    eventId: uuid(),
    occurredAt: new Date().toISOString(),
    eventVersion: event.eventVersion ?? 1,
  };
  await client.query(
    `INSERT INTO operations.outbox_events
      (id,event_type,event_version,aggregate_type,aggregate_id,merchant_id,correlation_id,payload)
     VALUES($1,$2,$3,$4,$5,$6,$7,$8)`,
    [envelope.eventId, envelope.eventType, envelope.eventVersion, envelope.aggregateType,
     envelope.aggregateId, envelope.merchantId, envelope.correlationId, envelope.payload],
  );
  return envelope;
}

