 * Locks the customer row and requires it to be writable. This serializes writers with the
 * erasure workflow so personal data cannot be (re)created once deletion has started.
 */
async assertCustomerWritable(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
  const result = await client.query<{ status: string }>(
    `SELECT status FROM customers.customers WHERE merchant_id=$1 AND id=$2 FOR UPDATE`,
    [merchantId, customerId],
  );
  const row = result.rows[0];
  if (!row) throw Object.assign(new Error('customer not found'), { statusCode: 404 });
  if (row.status !== 'active') throw Object.assign(new Error('customer is not active'), { statusCode: 409 });
}

