import { pool } from '../packages/database/src/pool.js';

const m = '10000000-0000-4000-8000-000000000001';
const c = '323dc249-91b0-4963-a676-ae4acc3ccb19';
const r = 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';

const statements: Array<[string, string, unknown[]]> = [
  ['outbox', `UPDATE operations.outbox_events SET payload=CASE
     WHEN aggregate_type='customer' AND aggregate_id=$2
       THEN jsonb_build_object('customerId',$3::text,'erased',true)
     ELSE jsonb_set(payload,'{customerId}',to_jsonb($3::text),false) - 'customerEmail' END
     WHERE merchant_id=$1 AND event_type<>'customer.erased.v1'
     AND ((aggregate_type='customer' AND aggregate_id=$2) OR payload->>'customerId'=$2::text)`, [m, c, r]],
  ['jobs', `UPDATE operations.jobs
     SET payload=jsonb_set(payload,'{customerId}',to_jsonb($3::text),false)
         || jsonb_build_object('customerSnapshot',jsonb_build_object('erased',true))
     WHERE merchant_id=$1 AND payload->>'customerId'=$2::text`, [m, c, r]],
  ['dead_letters', `UPDATE operations.dead_letters
     SET payload=jsonb_set(payload,'{customerId}',to_jsonb($2::text),false) - 'customerEmail'
     WHERE payload::text LIKE '%'||$1::text||'%'`, [c, r]],
  ['tombstone', `INSERT INTO customers.customers(id,merchant_id,external_reference,email,name,phone,status,metadata)
     VALUES($3,$1,'erased-'||$3::text,'erased-'||$3::text||'@erased.invalid','Erased Customer',NULL,'erased','{}')
     ON CONFLICT(id) DO NOTHING`, [m, c, r]],
  ['payment_intents', `UPDATE payments.payment_intents
     SET customer_id=$3,customer_snapshot=jsonb_build_object('id',$3::text,'erased',true),description=NULL
     WHERE merchant_id=$1 AND customer_id=$2`, [m, c, r]],
  ['payment_attempts', `UPDATE payments.payment_attempts a
     SET request_payload=jsonb_set(a.request_payload,'{customerId}',to_jsonb($3::text),false) - 'description'
     FROM payments.payment_intents p
     WHERE a.payment_intent_id=p.id AND p.merchant_id=$1 AND p.customer_id=$2`, [m, c, r]],
  ['sandbox', `UPDATE provider_sandbox.customers
     SET payflow_customer_id=$3,email='erased-'||id||'@erased.invalid',name='Erased Customer',
         external_reference='erased-'||$3::text,updated_at=now()
     WHERE merchant_id=$1 AND payflow_customer_id=$2`, [m, c, r]],
];

for (const [name, sql, params] of statements) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await client.query(sql, params);
    console.log('OK', name);
  } catch (error) {
    console.log('FAIL', name, (error as Error).message);
  } finally {
    await client.query('ROLLBACK').catch(() => undefined);
    client.release();
  }
}
await pool.end();

