import { randomUUID } from 'node:crypto';
import { producer, DOMAIN_TOPIC } from '../packages/messaging/src/kafka.js';

const merchant = '10000000-0000-4000-8000-000000000001';
const customer = '323dc249-91b0-4963-a676-ae4acc3ccb19';

const staleEvents = [
  {
    eventType: 'customer.created.v1', aggregateType: 'customer', aggregateId: customer,
    payload: {
      customerId: customer, email: 'ada.lovelace+mu3hqgt8@example.test', name: 'Ada Lovelace',
      phone: '+1-415-555-0101', externalReference: 'crm-ada-001-mu3hqgt8', metadata: { segment: 'enterprise' }, version: 1,
    },
  },
  {
    eventType: 'payment.succeeded.v1', aggregateType: 'payment_intent', aggregateId: 'ca2908d2-2072-43f6-b875-ad956be303f4',
    payload: {
      paymentId: 'ca2908d2-2072-43f6-b875-ad956be303f4', customerId: customer, amount: 2500,
      currency: 'USD', customerEmail: 'ada.lovelace+mu3hqgt8@example.test', receiptStatus: 'pending',
    },
  },
];

const kafka = producer();
await kafka.connect();
for (const [index, event] of staleEvents.entries()) {
  const envelope = {
    eventId: randomUUID(), eventType: event.eventType, eventVersion: 1,
    occurredAt: new Date(Date.now() - 86_400_000).toISOString(),
    aggregateType: event.aggregateType, aggregateId: event.aggregateId,
    merchantId: merchant, correlationId: randomUUID(), payload: event.payload,
  };
  await kafka.send({ topic: DOMAIN_TOPIC, messages: [{ key: event.aggregateId, value: JSON.stringify(envelope) }] });
  console.log(`replayed stale event ${index + 1}: ${event.eventType}`);
}
await kafka.disconnect();

